window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ec36e3783894e141"]={"versions": [{"id": "FIG-ec36e3783894e141", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster (Functional Clusters) innerhalb der Kategorie Security in der AUTOSAR Adaptive Platform Architektur. Es zeigt die logische Gliederung und Ausprägungsform sicherheitsrelevanter Plattformkomponenten auf Architekturebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Komponenten mit dem Stereotyp «aapFunctionalCluster»:</p>\n<ul class=\"fig-list\"><li><code>Cryptography</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Identity and Access Management</code>: Ohne gesonderte Daemon-Auszeichnung.\n</li><li><code>Adaptive Intrusion Detection System Manager</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Firewall</code>: Trägt das abgeschnittene Stereotyp <code>«aapFunctionalCl...</code> und ist als <code>daemon-based</code> deklariert.\n</li></ul>\n<p class=\"fig-p\">Zwischen den Clustern sind im Diagramm keine expliziten Schnittstellen, Ports oder Abhängigkeitsbeziehungen modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Übersicht der Cluster dar; dynamische Abläufe, Sequenzen oder Interaktionen zwischen den Sicherheitsclustern sind nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der funktionalen Cluster der Security-Domäne und ihrer Realisierung als daemon-basierte Plattformdienste. Die Kennzeichnung <code>daemon-based</code> erfordert für Cryptography, Adaptive Intrusion Detection System Manager und Firewall die Bereitstellung als eigenständige Betriebssystem-Prozesse (Daemons) mit entsprechenden IPC-Mechanismen für Clients. Identity and Access Management ist im Gegensatz dazu nicht explizit als daemon-basiert ausgewiesen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-44540462931645b6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster (Functional Clusters) innerhalb der Kategorie Security in der AUTOSAR Adaptive Platform Architektur. Es zeigt die logische Gliederung und Ausprägungsform sicherheitsrelevanter Plattformkomponenten auf Architekturebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten mit dem Stereotyp «aapFunctionalCluster»:</p>\n<ul class=\"fig-list\"><li><code>Cryptography</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Intrusion Detection System Manager</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Firewall</code>: Gekennzeichnet mit vollständigem Stereotyp <code>«aapFunctionalCluster»</code> und als <code>daemon-based</code> deklariert.\n</li></ul>\n<p class=\"fig-p\">Explizite Schnittstellen, Ports oder Abhängigkeitsbeziehungen zwischen den Komponenten sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Übersicht der Cluster dar; dynamische Abläufe, Sequenzen oder Interaktionen zwischen den Sicherheitsclustern sind nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der funktionalen Cluster der Kategorie Security. Alle dargestellten Cluster (<code>Cryptography</code>, <code>Intrusion Detection System Manager</code>, <code>Firewall</code>) sind verbindlich als <code>daemon-based</code> spezifiziert, wodurch für jedes dieser Cluster eine Implementierung als eigenständiger Daemon-Prozess im Betriebssystem der Adaptive Platform gefordert ist.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3af3026688562786", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster (Functional Clusters) innerhalb der Kategorie Security in der AUTOSAR Adaptive Platform Architektur. Es zeigt die logische Gliederung und Ausprägungsform sicherheitsrelevanter Plattformkomponenten auf Architekturebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten mit dem Stereotyp «aapFunctionalCluster»:</p>\n<ul class=\"fig-list\"><li><code>Cryptography</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Intrusion Detection System Manager</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Firewall</code>: Gekennzeichnet mit vollständigem Stereotyp <code>«aapFunctionalCluster»</code> und als <code>daemon-based</code> deklariert.\n</li></ul>\n<p class=\"fig-p\">Explizite Schnittstellen, Ports oder Abhängigkeitsbeziehungen zwischen den Komponenten sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Übersicht der Cluster dar; dynamische Abläufe, Sequenzen oder Interaktionen zwischen den Sicherheitsclustern sind nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der funktionalen Cluster der Kategorie Security. Alle dargestellten Cluster (<code>Cryptography</code>, <code>Intrusion Detection System Manager</code>, <code>Firewall</code>) sind verbindlich als <code>daemon-based</code> spezifiziert, wodurch für jedes dieser Cluster eine Implementierung als eigenständiger Daemon-Prozess im Betriebssystem der Adaptive Platform gefordert ist.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9ee2c1faedbcf1a8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster (Functional Clusters) innerhalb der Kategorie Security in der AUTOSAR Adaptive Platform Architektur. Es zeigt die logische Gliederung und Ausprägungsform sicherheitsrelevanter Plattformkomponenten auf Architekturebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Komponenten mit dem Stereotyp «aapFunctionalCluster»:</p>\n<ul class=\"fig-list\"><li><code>Cryptography</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Intrusion Detection System Manager</code>: Gekennzeichnet als <code>daemon-based</code>.\n</li><li><code>Firewall</code>: Gekennzeichnet mit vollständigem Stereotyp <code>«aapFunctionalCluster»</code> und als <code>daemon-based</code> deklariert.\n</li></ul>\n<p class=\"fig-p\">Explizite Schnittstellen, Ports oder Abhängigkeitsbeziehungen zwischen den Komponenten sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Übersicht der Cluster dar; dynamische Abläufe, Sequenzen oder Interaktionen zwischen den Sicherheitsclustern sind nicht abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der funktionalen Cluster der Kategorie Security. Alle dargestellten Cluster (<code>Cryptography</code>, <code>Intrusion Detection System Manager</code>, <code>Firewall</code>) sind verbindlich als <code>daemon-based</code> spezifiziert, wodurch für jedes dieser Cluster eine Implementierung als eigenständiger Daemon-Prozess im Betriebssystem der Adaptive Platform gefordert ist.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ec36e3783894e141", "to": "FIG-44540462931645b6", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Das Functional Cluster <code>Identity and Access Management</code> entfällt aus der Kategorie Security.\n</li><li>Das Functional Cluster <code>Adaptive Intrusion Detection System Manager</code> wurde umbenannt in <code>Intrusion Detection System Manager</code>.\n</li><li>Die Beschriftung des Stereotyps beim Functional Cluster <code>Firewall</code> ist korrigiert (zuvor abgeschnitten als <code>«aapFunctionalCl...</code>, nun vollständig als <code>«aapFunctionalCluster»</code>).\n</li></ul>"}, {"from": "FIG-44540462931645b6", "to": "FIG-3af3026688562786", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3af3026688562786", "to": "FIG-9ee2c1faedbcf1a8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
